const barCache: Record<string, OHLCVBar[]> = {};

export const RECORDED_BARS: Record<string, OHLCVBar[]> = new Proxy({}, {
  get(_target, prop: string | symbol) {
    if (typeof prop !== "string") return undefined;
    const key = prop.toUpperCase();
    if (barCache[key]) return barCache[key];
    const entry = RAW_BARS[key];
    if (!entry) return undefined;
    const [setIdx, rows] = entry;
    const dates = DATE_SETS[setIdx];
    const bars: OHLCVBar[] = rows.map((r, i) => ({
      time: dates[i],
      open: r[0],
      high: r[1],
      low: r[2],
      close: r[3],
      volume: r[4],
    }));
    barCache[key] = bars;
    return bars;
  },
  has(_target, prop: string | symbol) {
    return typeof prop === "string" && prop.toUpperCase() in RAW_BARS;
  },
  ownKeys() {
    return Object.keys(RAW_BARS);
  },
  getOwnPropertyDescriptor(_target, prop: string | symbol) {
    if (typeof prop === "string" && prop.toUpperCase() in RAW_BARS) {
      return { enumerable: true, configurable: true, value: (RECORDED_BARS as any)[prop] };
    }
    return undefined;
  },
});
